import type { ReactNode } from "react";

interface CardProps {
  title: string;
  body: string;
  children?: ReactNode;
}

export function Card({ title, body, children }: CardProps) {
  return (
    <section className="card">
      <h3>{title}</h3>
      <p dangerouslySetInnerHTML={{ __html: body }} />
      {children}
    </section>
  );
}
